  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Leading Worship with a Servant Heart$j$, $j${"readings": [{"title": "Psalm 24 (King James Version)", "url": "/portal/bible/Psalms/24"}], "body": "A worship leader helps a congregation turn its heart to God. The task is a service, not a stage. Psalm 24:3 and 4 asks, Who shall ascend into the hill of the LORD? or who shall stand in his holy place? He that hath clean hands, and a pure heart. Character matters more than talent. A leader should pray, read Scripture, live with honesty and humility, and be teachable.\n\nPreparation is part of service. Begin with prayer and with the pastor's direction, since the music should serve the message and the needs of the church. Hebrews 13:17 asks believers to obey them that have the rule over you, and submit yourselves. Choose songs that are true to Scripture, that the people can sing, and that fit the service. Think about range, because most congregations sing comfortably within about an octave and a half, and avoid keys that are too high or low. Teach new songs gradually and repeat them. Plan the order, the keys and the transitions. Prepare the team, the sound and the words on the screen or in the hymnal.\n\nLead with clarity. Give the congregation clear cues, such as a short introduction, and a visible beat. Speak briefly and sincerely, and point people to Christ, not to yourself. Sing with the congregation and invite them to join, and keep the volume of the band from drowning out their voices. Be on time, dress modestly and neatly, and respect those who serve on the sound, video and children's teams.\n\nHandle mistakes with grace. If something goes wrong, keep going calmly and give thanks. Be gracious to those who disagree on style, and honor your elders. Serve out of love for God and for people. First Corinthians 14:26 says, Let all things be done unto edifying. Edifying means building up.\n\nYour task: (1) Explain why character matters for a worship leader. (2) List five steps in preparing for a service. (3) Explain First Corinthians 14:26 and how it guides song choice.\n\nFlorida standards: MU.912.C.3, MU.912.S.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.C.3, MU.912.S.3", "script": "Welcome to Unit 6. Listen, to lead worship is to serve, and the stage is only a place to stand while pointing to Christ.\n\nA worship leader helps a congregation turn its heart to God. Psalm 24:3 and 4 asks, Who shall ascend into the hill of the LORD? or who shall stand in his holy place? He that hath clean hands, and a pure heart. Character matters more than talent. Pray, read Scripture, live honestly and stay teachable.\n\nNow watch this. Preparation is part of service. Begin with prayer and with your pastor's direction, since the music should serve the message and the needs of the church. Hebrews 13:17 asks believers to submit to those who have the rule over them. Choose songs that are true to Scripture, singable and fitting for the service. Think about range, because most congregations sing comfortably within about an octave and a half. Teach new songs gradually. Plan the order, keys and transitions, and prepare the team and the sound.\n\nLook at the leading itself. Give clear cues, a short introduction and a visible beat. Speak briefly and sincerely. Point people to Christ, not yourself. Do not let the band drown out the congregation. Be on time, dress neatly, and respect the sound, video and children's teams.\n\nIf something goes wrong, keep going calmly. First Corinthians 14:26. Let all things be done unto edifying.\n\nYour task is to explain why character matters, list five steps of preparation and explain First Corinthians 14:26. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Leading Worship with a Servant Heart$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Listening Critically and Appreciating Music$j$, $j${"readings": [{"title": "Proverbs 2 (King James Version)", "url": "/portal/bible/Proverbs/2"}], "body": "A good listener does more than hear. Active listening means paying close attention to what the music is doing and thinking about it. Proverbs 2:2 speaks of inclining thine ear unto wisdom, and a good listener learns to incline the ear.\n\nUse the elements of music to describe what you hear. Listen for rhythm and meter, and tap the beat. Listen to the melody and its contour. Notice the harmony and the texture. Describe the tempo and the dynamics, and any changes. Name the instruments or voices and their timbre. Follow the form, and note when themes return. Then think about the mood, the message and the purpose of the piece. Was it written for worship, dance, celebration, mourning or entertainment? When and where was it written, and by whom?\n\nWrite about music with clear, specific words. Instead of saying that a piece was good, say what happened. For example, the trumpet entered after the quiet strings, and the loud brass section made the ending feel triumphant. Compare two pieces and explain similarities and differences. Give reasons for your opinions, and be fair to pieces that are unfamiliar.\n\nAttend live performances when you can. At a concert, arrive on time, silence your phone, stay quiet during the music and applaud at the proper times. At a church service, the congregation sings, so participate. In a classical concert, listeners usually wait to applaud until a complete work ends, not between movements. Respect for performers and listeners is part of courtesy.\n\nA listening journal records the date, the piece, the performer, what you heard, and what you thought. Keep one through this course. It will help you grow as a listener and give you a record of your discoveries.\n\nYour task: (1) Explain active listening. (2) Use five elements of music to describe a piece. (3) List four rules of concert courtesy.\n\nFlorida standards: MU.912.C.1, MU.912.C.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.C.1, MU.912.C.2", "script": "Welcome back. Listen, there is a big difference between hearing and listening. Let us learn to listen with understanding.\n\nActive listening means paying close attention to what the music is doing and thinking about it. Proverbs 2:2 speaks of inclining thine ear unto wisdom.\n\nNow watch this. Use the elements to describe what you hear. Tap the beat and name the meter. Follow the melody and its contour. Notice the harmony and texture. Describe the tempo and dynamics and any changes. Name the instruments or voices and their timbre. Follow the form and note when themes return. Then ask about mood, message and purpose. Was it written for worship, dance, celebration, mourning or entertainment?\n\nLook at how to write about music. Be specific. Instead of saying it was good, say what happened. For example, the trumpet entered after the quiet strings, and the loud brass made the ending feel triumphant. Compare two pieces, give reasons for your opinions and be fair to unfamiliar music.\n\nAttend live performances when you can. Arrive on time, silence your phone, stay quiet during the music and applaud at the proper times. In a classical concert, listeners usually wait to applaud until a complete work ends. Keep a listening journal with the date, piece, performer, what you heard and what you thought.\n\nYour task is to explain active listening, describe a piece with five elements and list four rules of courtesy. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Listening Critically and Appreciating Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Music, Technology, Copyright and Honesty$j$, $j${"readings": [{"title": "Exodus 20 (King James Version)", "url": "/portal/bible/Exodus/20"}], "body": "Technology makes music easy to record, copy and share. It also raises questions about honesty. Copyright is the legal protection given to creators of original works, including songs, recordings and written music. In the United States, a work is protected automatically once it is created and fixed in a form such as a recording or written score. Copyright gives the owner the right to decide who may copy, perform, record and distribute the work. When copyright ends, a work enters the public domain, where anyone may use it. Many old hymns are in the public domain, though a particular modern arrangement or recording may still be protected, so check before using one.\n\nHonesty and fairness apply to music. Exodus 20:15 says, Thou shalt not steal. Luke 10:7 says, for the labourer is worthy of his hire. Songwriters, musicians and engineers earn their living by their work, and taking their music without permission harms them. Do not download or share music illegally, and do not copy recordings or sheet music you have not bought or been licensed to use. Use legal services that pay the creators.\n\nChurches have special concerns. When a church projects song lyrics, prints them in a bulletin, or streams a service online with music, it usually needs a license or permission. Many churches buy a license through a company that collects fees for songwriters, such as CCLI. Music directors and pastors should know what their license covers. This is general education and not legal advice, so ask your pastor or music director to confirm the church's license and policies.\n\nBe honest about how music is made. If you use software, samples or artificial intelligence to help make music, give credit where it is due and follow the rules of the tools you use. Do not claim that someone else's work is yours. Colossians 3:9 says, Lie not one to another. Create and share in ways that honor God and respect others.\n\nYour task: (1) Define copyright and public domain. (2) Explain why illegal downloading is wrong. (3) Explain why a church may need a license.\n\nFlorida standards: MU.912.F.1, MU.912.C.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.F.1, MU.912.C.3", "script": "Welcome back. Listen, a song you love was made by a person who worked hard. Today we talk about honesty and respect for that work.\n\nCopyright is the legal protection given to creators of original works, including songs, recordings and written music. In the United States, a work is protected automatically once it is created and fixed in a form like a recording or a score. The owner decides who may copy, perform, record and distribute it. When copyright ends, a work enters the public domain, where anyone may use it. Many old hymns are in the public domain, but a modern arrangement or recording may still be protected, so check first.\n\nNow watch this. Exodus 20:15 says, Thou shalt not steal. Luke 10:7, the labourer is worthy of his hire. Songwriters, musicians and engineers earn their living from their work. Taking music without permission harms them. Do not download or share music illegally. Use legal services that pay the creators.\n\nLook at the church. When a church projects lyrics, prints them in a bulletin or streams a service with music, it usually needs a license or permission. Many churches buy one through a company such as CCLI. This is general education and not legal advice, so ask your pastor or music director what your church's license covers.\n\nBe honest about how music is made. Give credit, follow the rules of your tools, and never claim someone else's work as yours. Colossians 3:9. Lie not one to another.\n\nYour task is to define copyright and public domain, explain why illegal downloading is wrong and explain why a church may need a license. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Music, Technology, Copyright and Honesty$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Music for Life and for Service$j$, $j${"readings": [{"title": "Romans 12 (King James Version)", "url": "/portal/bible/Romans/12"}], "body": "Music is a lifelong gift. A person does not have to become a professional to benefit from it. People of every age sing in choirs, play in community bands, lead children in songs, play at weddings and funerals, and enjoy recordings. Music can help people relax, focus, remember and connect with one another. It is wise to speak carefully about health claims, but many people find music calming and encouraging.\n\nThere are many careers in music. They include church musician, choir director, music teacher, performer, composer, songwriter, arranger, recording engineer, sound technician, instrument maker and repairer, music therapist, music librarian, and music business professional. Many require study, practice and certification. Music therapists, for example, are trained professionals who use music to help patients. Students interested in music careers can take classes, join school and church ensembles, study privately, and learn recording and sound skills. Many people use their music as a ministry alongside another career.\n\nMusic is a way to serve. You can sing in the church choir, play for a children's class, help with the sound team, or teach a younger student. With permission and supervision from adults, you can bring songs to a nursing home or a hospital. You can lead family worship at home. Romans 12:6 says, Having then gifts differing according to the grace that is given to us, let us use them. First Peter 4:10 says to minister the gift one to another, as good stewards of the manifold grace of God. Always get permission and supervision from parents, guardians and church leaders before serving outside your home or church.\n\nKeep learning. Listen to a wide range of music, read about composers and styles, practice, and keep a journal. Ephesians 5:19 and Colossians 3:16 remind us that the Christian life is one that sings. Revelation 5:9 pictures a new song in heaven, and we begin to rehearse here.\n\nYour task: (1) Name five careers in music. (2) Describe three ways to serve with music. (3) Write a plan for how you will keep music in your life.\n\nFlorida standards: MU.912.C.3, MU.912.F.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.C.3, MU.912.F.1", "script": "Welcome to our last lesson. Listen, this course does not end today. Music is a lifelong gift.\n\nMusic can help people relax, focus, remember and connect. People of every age sing in choirs, play in community bands, lead children in songs, play at weddings and funerals and enjoy recordings. You do not have to be a professional to benefit.\n\nNow watch this. There are many careers in music. Church musician, choir director, music teacher, performer, composer, songwriter, arranger, recording engineer, sound technician, instrument maker and repairer, music therapist, music librarian and music business professional. A music therapist is a trained professional who uses music to help patients. To prepare, take classes, join school and church ensembles, study privately and learn recording and sound skills. Many people use music as a ministry alongside another career.\n\nLook at service. Sing in the church choir. Play for a children's class. Help the sound team. Teach a younger student. With adult permission and supervision, bring songs to a nursing home or hospital. Lead family worship at home. Romans 12:6. Having then gifts differing according to the grace that is given to us, let us use them. First Peter 4:10 says to minister the gift as good stewards of the manifold grace of God.\n\nKeep learning. Listen widely, practice, and keep your journal. Revelation 5:9 pictures a new song in heaven. We begin to rehearse here.\n\nYour task is to name five careers, describe three ways to serve with music and write a plan for music in your life. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Music for Life and for Service$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Worship Arts and Lifelong Listening$j$, $j${"prompt": "Write a report of at least 250 words on worship arts and lifelong listening. Use complete sentences and label each part. First Corinthians 14:26 says, Let all things be done unto edifying.\n\nPart 1: Describe the character, preparation and skills of a worship leader.\nPart 2: Explain active listening and use at least five elements of music to describe one piece you have heard this week.\nPart 3: Explain copyright, public domain and why honesty matters when using or sharing music.\nPart 4: Name five careers in music and three ways you can serve with music.\nPart 5: Write a personal music plan for the next year that includes listening, practice, learning and service. Include at least five entries from your listening journal.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 15 points. Part 4: 15 points. Part 5: 25 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Worship Arts and Lifelong Listening$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: A Life That Sings$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells how you plan to use music to serve God and others, (2) explains why honesty and respect for creators matter in the age of streaming and sharing, (3) describes one way you could help your church or community with music, and (4) connects your answer to Romans 12:6 or First Peter 4:10. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is character more important than talent for a worship leader? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: A Life That Sings$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Leading Worship with a Servant Heart$j$, $j${"questions": [{"q": "A worship leader should first be concerned with:", "options": ["Character and a servant heart", "Wearing the latest style", "Making a recording", "Being the loudest"]}, {"q": "Songs for congregational singing should be:", "options": ["Only new", "True to Scripture and singable", "Only fast", "Very difficult"]}, {"q": "Edifying means:", "options": ["Tearing down", "Silencing", "Entertaining", "Building up"]}, {"q": "A good worship leader points people to:", "options": ["Christ", "The band", "The leader", "The lights"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Leading Worship with a Servant Heart$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$Psalm 24:4 stresses clean hands and a pure heart.$j$,$j$A congregation needs songs it can sing and that are true.$j$,$j$Worship should build up the church.$j$,$j$The goal is to honor Christ.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Leading Worship with a Servant Heart$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Listening Critically and Appreciating Music$j$, $j${"questions": [{"q": "Active listening means:", "options": ["Paying close attention and thinking about the music", "Skipping to the end", "Hearing music in the background", "Talking during a piece"]}, {"q": "A strong way to describe music is to:", "options": ["Use specific details from the elements", "Say only that it was good", "Say only that it was bad", "Avoid describing it"]}, {"q": "At a concert, you should:", "options": ["Silence your phone", "Leave in the middle", "Talk during the music", "Use a flashlight"]}, {"q": "A listening journal records:", "options": ["Only the weather", "The piece, performer, what you heard and what you thought", "Only the price", "Nothing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Listening Critically and Appreciating Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,1}'::int[], array[$j$Active listeners notice and think.$j$,$j$Specific details show real listening.$j$,$j$Courtesy shows respect for performers and listeners.$j$,$j$It builds listening skill over time.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Listening Critically and Appreciating Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Music, Technology, Copyright and Honesty$j$, $j${"questions": [{"q": "Copyright is:", "options": ["A hymnal", "A choir part", "Legal protection for creators of original works", "A kind of tempo"]}, {"q": "When a work is in the public domain:", "options": ["It cannot be heard", "It must be destroyed", "Only churches may use it", "Anyone may use it"]}, {"q": "Exodus 20:15 says:", "options": ["Thou shalt not steal", "Sing a new song", "Blow the trumpet", "Honor the sabbath"]}, {"q": "A church that projects lyrics usually needs:", "options": ["A louder speaker", "A bigger screen", "A new organ", "A license or permission"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Music, Technology, Copyright and Honesty$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,3}'::int[], array[$j$Copyright protects songs, recordings and scores.$j$,$j$The public domain is free for all to use.$j$,$j$Taking music without permission is a form of stealing.$j$,$j$Churches should know what their license covers.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Music, Technology, Copyright and Honesty$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Music for Life and for Service$j$, $j${"questions": [{"q": "A music therapist is:", "options": ["A kind of instrument", "A form of notation", "A choir part", "A trained professional who uses music to help patients"]}, {"q": "Before serving with music outside your home or church, you should:", "options": ["Wait until midnight", "Skip permission", "Get permission and supervision from parents and leaders", "Go alone"]}, {"q": "Romans 12:6 says we have gifts:", "options": ["That cannot be used", "Differing according to the grace that is given to us", "That are only for adults", "That are all the same"]}, {"q": "One way to keep growing in music is to:", "options": ["Avoid new music", "Listen widely, practice and keep a journal", "Stop practicing", "Only listen to one song"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Music for Life and for Service$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,1,1}'::int[], array[$j$Music therapy requires training.$j$,$j$Adult permission keeps service safe.$j$,$j$God gives differing gifts to use in service.$j$,$j$Lifelong learning keeps skill growing.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Music for Life and for Service$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Worship Arts and Lifelong Listening$j$, $j${"questions": [{"q": "Psalm 24:4 says who may stand in God's holy place:", "options": ["The loudest singer", "He that hath clean hands, and a pure heart", "The best dressed", "The richest"]}, {"q": "Songs for a congregation should fit a comfortable range of about:", "options": ["An octave and a half", "Ten octaves", "Five octaves", "One note"]}, {"q": "Active listening includes:", "options": ["Describing elements such as rhythm, melody and timbre", "Talking during the piece", "Skipping the ending", "Ignoring the music"]}, {"q": "Copyright is automatic when a work is:", "options": ["Sold", "Created and fixed in a form such as a recording or score", "Approved by a judge", "Played in public only"]}, {"q": "A church that streams music usually needs:", "options": ["A larger screen only", "A new building", "A license or permission", "No approval"]}, {"q": "One music career is:", "options": ["Pilot", "Plumber", "Surveyor", "Recording engineer"]}, {"q": "Before serving at a nursing home with music, a teen should:", "options": ["Go alone", "Get adult permission and supervision", "Sing without telling anyone", "Skip planning"]}, {"q": "Revelation 5:9 pictures:", "options": ["A trumpet contest", "A concert tour", "A silent heaven", "A new song in heaven"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Worship Arts and Lifelong Listening$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,1,2,3,1,3}'::int[], array[$j$Character matters most.$j$,$j$Most congregations sing comfortably in a limited range.$j$,$j$Active listening applies the elements.$j$,$j$Protection begins when the work is fixed.$j$,$j$Check what the license covers.$j$,$j$Recording engineers capture and mix sound.$j$,$j$Adult oversight keeps service safe.$j$,$j$Believers begin to rehearse that song here.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Worship Arts and Lifelong Listening$j$ on conflict (item_id) do nothing;
